import { readdir, readFile, writeFile, mkdir } from 'node:fs/promises';
import path from 'node:path';
import { format } from 'prettier';
import { fileURLToPath } from 'node:url';
export async function generateRegistry(root = process.cwd(), check = false) {
  const files = (await readdir(path.join(root, 'data/cities')))
    .filter((x) => /^[a-z][a-z0-9-]*\.json$/.test(x))
    .sort();
  const raw =
    "// Generated by city:registry. Only reviewed, published data belongs here.\nimport denver from '../../data/denver-places.json';\n" +
    files.map((f, i) => `import city${i} from '../../data/cities/${f}';\n`).join('') +
    `export const catalogueSnapshots = [denver${files.map((_, i) => `, city${i}`).join('')}];\n`;
  const text = await format(raw, {
    parser: 'typescript',
    singleQuote: true,
    trailingComma: 'all',
    printWidth: 100,
  });
  const target = path.join(root, 'src/generated/catalogues.ts');
  if (check) {
    if ((await readFile(target, 'utf8')) !== text)
      throw new Error('City registry is stale. Run npm run city:registry.');
  } else {
    await mkdir(path.dirname(target), { recursive: true });
    await writeFile(target, text);
  }
  return files;
}
if (process.argv[1] === fileURLToPath(import.meta.url))
  await generateRegistry(process.cwd(), process.argv.includes('--check'));
